/* hs:pharma-catalyst-radar: statisch, quellengebunden, keine Live-API */
.ph-catalyst-radar{margin:24px 0 22px;padding:28px;border:1px solid var(--line);border-radius:24px;background:linear-gradient(135deg,rgba(20,50,62,.88),rgba(11,26,39,.96));box-shadow:0 12px 32px rgba(0,0,0,.16)}
.ph-catalyst-head{display:flex;gap:20px;align-items:flex-end;justify-content:space-between;margin-bottom:18px}.ph-catalyst-head h2{margin:7px 0 0;font-size:28px}.ph-catalyst-head p{margin:0;max-width:620px;color:var(--soft)}
.ph-radar-eyebrow,.ph-radar-kind{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#91d9e4;font-weight:700}.ph-radar-eyebrow{display:block}.ph-radar-stamp{font-size:12px;color:#b4cad2;white-space:nowrap}
.ph-radar-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.ph-radar-card{border:1px solid rgba(132,181,194,.42);border-radius:17px;padding:18px;background:rgba(7,22,34,.56);display:flex;flex-direction:column;min-width:0}.ph-radar-card h3{margin:10px 0 10px;font-size:19px;line-height:1.25;color:var(--text)}.ph-radar-card p{margin:0 0 11px;line-height:1.58;color:var(--soft)}.ph-radar-card .ph-radar-context{font-size:14px;color:#b9cbd1}.ph-radar-links{margin-top:auto;padding-top:4px}.ph-radar-links a{display:block;color:#a7e4ef;font-size:14px;line-height:1.45;text-decoration:underline;text-underline-offset:3px}.ph-radar-disclosure{margin:12px 0 0;padding-top:12px;border-top:1px solid rgba(132,181,194,.28);font-size:12px;line-height:1.55;color:#c7d6da}.ph-radar-foot{margin:17px 0 0;font-size:13px;line-height:1.55;color:#b9cbd1}.ph-radar-foot a{color:#a7e4ef}.ph-radar-method{margin-top:8px;font-size:12px;color:#aebfc5}
@media(max-width:900px){.ph-catalyst-head{display:block}.ph-catalyst-head h2{font-size:25px}.ph-radar-stamp{display:block;margin-top:10px;white-space:normal}.ph-radar-grid{grid-template-columns:1fr}.ph-catalyst-radar{padding:21px}}
</style>
